'use strict';
const mantraState={selected:'gayatri',topic:'all',query:'',kind:'all',lang:'both'};
try{const language=JSON.parse(localStorage.getItem('dharma-mantra-lang'));if(['both','sa','hi','en'].includes(language))mantraState.lang=language;}catch{}
const mantraNormalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase().trim();
function matchingMantras(){
  const query=mantraNormalize(mantraState.query);
  return MANTRAS.filter(m=>(mantraState.topic==='all'||m.topics.includes(mantraState.topic))&&(mantraState.kind==='all'||m.kind===mantraState.kind)&&(!query||mantraNormalize([m.title,m.saTitle,m.sanskrit,m.roman,m.en,m.hi,m.ref,m.kind,...m.topics.map(id=>MANTRA_TOPICS.find(t=>t[0]===id).slice(1).join(' '))].join(' ')).includes(query)));
}
function mantraLanguageButtons(){return `<div class="segmented mantra-languages" aria-label="Reading mode">${[['both','All three'],['sa','संस्कृत'],['hi','हिन्दी'],['en','English']].map(([id,name])=>`<button data-mantra-lang="${id}" class="${mantraState.lang===id?'selected':''}" aria-pressed="${mantraState.lang===id}">${name}</button>`).join('')}</div>`;}
function mantras(){return `<section class="mantra-intro"><div><p class="eyebrow">मन्त्र एवं प्रार्थना · MANTRAS & PRAYERS</p><h1>A moment to pause.<br><em>A verse to return to.</em></h1><p class="lede">Words for what you’re feeling, and the life you’re living.<br>Read slowly. Understand the meaning. Carry it into your day.</p><div class="intro-meta"><span><b>${MANTRAS.length}</b> complete passages</span><i></i><span>संस्कृत · हिन्दी · English</span></div></div><div class="mantra-seal" aria-hidden="true"><span>ॐ</span><small>शान्तिः शान्तिः शान्तिः</small></div></section><section class="mantra-discovery" aria-labelledby="mantra-feeling-title"><div class="section-heading"><h2 id="mantra-feeling-title">What do you need today?</h2><span class="small-label">BEGIN WITH A FEELING</span></div><div class="chips mantra-topics"><button class="chip ${mantraState.topic==='all'?'selected':''}" data-mantra-topic="all" aria-pressed="${mantraState.topic==='all'}">All passages</button>${MANTRA_TOPICS.map(([id,en,hi])=>`<button class="chip ${mantraState.topic===id?'selected':''}" data-mantra-topic="${id}" aria-pressed="${mantraState.topic===id}" title="${hi}">${en}<span lang="hi">${hi}</span></button>`).join('')}</div><div class="mantra-search-tools"><div class="mantra-search">${icon('search',19)}<label class="sr-only" for="mantra-search">Search mantras in Sanskrit, Hindi or English</label><input id="mantra-search" type="search" maxlength="160" value="${esc(mantraState.query)}" placeholder="Try anxiety, exams, gratitude, शान्ति…" autocomplete="off"></div><label class="mantra-kind"><span class="sr-only">Type of passage</span><select id="mantra-kind"><option value="all">All text traditions</option>${['Vedic mantra','Upanishadic mantra','Prayer verse','Gita verse'].map(k=>`<option value="${k}" ${mantraState.kind===k?'selected':''}>${k}</option>`).join('')}</select></label></div><p class="mantra-results-status" id="mantra-results-status" role="status" aria-live="polite"></p></section><div class="mantra-workspace"><aside class="mantra-index"><div class="mantra-index-heading"><span class="small-label">THE COLLECTION</span><span lang="sa">मन्त्रसंग्रह</span></div><nav class="mantra-list" id="mantra-list" aria-label="Choose a mantra or prayer"></nav></aside><div id="mantra-reading"></div></div><details class="mantra-editorial-note"><summary>${icon('shield',17)} About the texts and their sources</summary><p>Each entry includes a complete selected mantra, prayer or verse—not a half-verse. A verse from a longer hymn is labelled with its location; it is not presented as the entire hymn. Traditional recensions can differ. Sanskrit is displayed without Vedic pitch accents, and the Roman text is a transliteration rather than an English translation.</p><p>Hindi and English meanings are plain-language editorial renderings. Feeling categories and daily reflections are suggestions for applying the text, not prescribed rituals or promises of particular outcomes. Each entry links to a source for comparison, with variant or attribution notes where needed.</p><a class="text-button" href="#sources">Our sources & approach ${icon('arrow',15)}</a></details>`;}
function mantraDetail(m,found){
  const lang=mantraState.lang,english=lang==='en'||lang==='both',hindi=lang==='hi'||lang==='both',index=found.indexOf(m);
  return `<article class="verse-paper mantra-paper" aria-labelledby="mantra-title"><div class="mantra-paper-top"><span class="badge subtle">${esc(m.kind)}</span><span class="small-label">COMPLETE TEXT · पूर्ण पाठ</span></div><div class="mantra-heading"><p class="eyebrow" lang="sa">${esc(m.saTitle)}</p><h2 id="mantra-title" tabindex="-1">${esc(m.title)}</h2><p class="mantra-reference">${esc(m.ref)}</p></div><div class="mantra-reading-controls">${mantraLanguageButtons()}</div><div class="mantra-body"><div class="ornament" aria-hidden="true">✧</div><div class="sanskrit mantra-sanskrit" lang="sa">${esc(m.sanskrit)}</div>${english?`<details class="roman mantra-roman" open><summary>Roman transliteration</summary><p lang="sa-Latn">${esc(m.roman)}</p></details>`:lang==='sa'?`<details class="roman mantra-roman"><summary>Roman transliteration</summary><p lang="sa-Latn">${esc(m.roman)}</p></details>`:''}${english||hindi?`<div class="translation mantra-translation ${lang==='both'?'two-languages':''}">${english?`<div lang="en"><span class="small-label">ENGLISH MEANING</span><p>${esc(m.en)}</p></div>`:''}${hindi?`<div lang="hi"><span class="small-label">हिन्दी अर्थ</span><p>${esc(m.hi)}</p></div>`:''}</div><p class="attribution mantra-attribution">${lang==='hi'?'सरल भावार्थ · धर्म का सम्पादकीय अनुवाद':'Plain-language meaning · Dharma editorial translation'}</p>`:''}<div class="mantra-use"><span class="small-label">${lang==='hi'?'चिन्तन के विषय':'A COMPANION FOR'}</span><p>${m.topics.map(id=>{const t=MANTRA_TOPICS.find(t=>t[0]===id);return `<button class="mantra-topic-link" data-mantra-topic="${id}">${esc(lang==='hi'?t[2]:t[1])}</button>`;}).join('<span aria-hidden="true"> · </span>')}</p></div><div class="real-life mantra-reflection"><span class="small-label">${lang==='hi'?'जीवन में एक छोटा अभ्यास':'CARRY IT INTO TODAY'} · ${lang==='hi'?'सम्पादकीय चिन्तन':'EDITORIAL REFLECTION'}</span>${lang!=='hi'?`<p>${esc(m.practice)}</p>`:''}${lang==='hi'||lang==='both'?`<p lang="hi">${esc(m.practiceHi)}</p>`:''}</div><div class="mantra-provenance"><p class="small-label">TEXT & CONTEXT</p>${sourceLink(m.url,MANTRA_SOURCES[m.source].name+(m.page?' · p. '+m.page:''))}${m.note?`<p class="fine-print">${esc(m.note)}</p>`:''}</div></div><div class="verse-bottom mantra-bottom"><button class="text-button" data-mantra-step="-1" ${index===0?'disabled':''}>${icon('left',16)} Previous</button><span>${index+1} / ${found.length} in this selection</span><button class="text-button" data-mantra-step="1" ${index===found.length-1?'disabled':''}>Next ${icon('right',16)}</button></div></article>`;
}
function refreshMantras(){
  if(state.page!=='mantras')return;
  const found=matchingMantras(),listScroll=$('#mantra-list')?.scrollTop||0;
  if(found.length&&!found.some(m=>m.id===mantraState.selected))mantraState.selected=found[0].id;
  const m=found.find(m=>m.id===mantraState.selected);
  document.querySelectorAll('.mantra-topics [data-mantra-topic]').forEach(b=>{const active=b.dataset.mantraTopic===mantraState.topic;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',active)});
  $('#mantra-results-status').textContent=`${found.length} of ${MANTRAS.length} complete passages${mantraState.topic!=='all'?' · '+MANTRA_TOPICS.find(t=>t[0]===mantraState.topic)[1]:''}${mantraState.query?' · matching “'+mantraState.query+'”':''}`;
  $('#mantra-list').innerHTML=found.map(x=>`<button class="mantra-list-item ${x.id===mantraState.selected?'selected':''}" data-mantra-id="${x.id}" aria-pressed="${x.id===mantraState.selected}"><span class="mantra-list-number">${String(MANTRAS.indexOf(x)+1).padStart(2,'0')}</span><span><strong>${esc(x.title)}</strong><span lang="sa">${esc(x.saTitle)}</span><small>${esc(x.kind)}</small></span>${icon('right',15)}</button>`).join('')||'<p class="mantra-list-empty">No matching passages.</p>';
  $('#mantra-list').scrollTop=listScroll;
  $('#mantra-reading').innerHTML=m?mantraDetail(m,found):`<div class="panel mantra-empty"><span lang="sa">अथ अन्वेषणम्</span><h2>No passages match these filters.</h2><p>Try a shorter word in English, Hindi or Sanskrit, or explore another feeling.</p><button class="btn primary" data-mantra-reset="true">Show all 54 passages</button></div>`;
}
function bindMantras(){if(state.page!=='mantras')return;$('#mantra-search')?.addEventListener('input',e=>{mantraState.query=e.target.value;refreshMantras()});$('#mantra-kind')?.addEventListener('change',e=>{mantraState.kind=e.target.value;refreshMantras()});refreshMantras();}
function selectMantra(id,focus=true){if(!MANTRAS.some(m=>m.id===id))return;const turn=id!==mantraState.selected?capturePageTurn('.mantra-body'):null,direction=MANTRAS.findIndex(m=>m.id===id)-MANTRAS.findIndex(m=>m.id===mantraState.selected);mantraState.selected=id;history.replaceState(null,'','#mantras/'+id);refreshMantras();finishPageTurn(turn,'.mantra-body',direction);if(focus)$('#mantra-title')?.focus({preventScroll:true});if(typeof window.matchMedia==='function'&&window.matchMedia('(max-width: 1000px)').matches)$('#mantra-reading')?.scrollIntoView({behavior:'smooth',block:'start'});}
document.querySelector('#app').addEventListener('click',e=>{
  const b=e.target.closest('button');if(!b||state.page!=='mantras')return;const d=b.dataset;
  if(d.mantraId)selectMantra(d.mantraId);
  if(d.mantraTopic){mantraState.topic=d.mantraTopic;refreshMantras();}
  if(d.mantraLang){mantraState.lang=d.mantraLang;storage.set('dharma-mantra-lang',d.mantraLang);refreshMantras();document.querySelector(`[data-mantra-lang="${d.mantraLang}"]`)?.focus({preventScroll:true});}
  if(d.mantraStep){const found=matchingMantras(),i=found.findIndex(m=>m.id===mantraState.selected),next=found[i+Number(d.mantraStep)];if(next)selectMantra(next.id);}
  if(d.mantraReset){mantraState.topic='all';mantraState.query='';mantraState.kind='all';$('#mantra-search').value='';$('#mantra-kind').value='all';refreshMantras();$('#mantra-search').focus();}
});
